1	package org.springframework.samples.petclinic.model;
2	
3	import java.time.LocalDate;
4	import java.time.temporal.ChronoUnit;
5	
6	/**
7	 * Derives an owner's membership standing, assigned on create.
8	 *
9	 * <p>A points total is accumulated from four factors, starting at 0:
10	 * <ul>
11	 *   <li>+{@link #POINTS_EMAIL} (2) when an email is present;</li>
12	 *   <li>+{@link #POINTS_UNIQUE_NAME} (1) when the owner's {@code namesakeCount} is 0 (the name was
13	 *       unique on create);</li>
14	 *   <li>+{@link #POINTS_HOUSEHOLD} (2) for a household of {@link #HOUSEHOLD_SIZE_FOR_POINTS} (3) or
15	 *       more members;</li>
16	 *   <li>+{@link #POINTS_TENURE} (3) when the owner has been registered for more than
17	 *       {@link #TENURE_DAYS_FOR_POINTS} (365) days.</li>
18	 * </ul>
19	 *
20	 * <p>The points total maps to a numeric level: 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6 or
21	 * more.
22	 *
23	 * <p>This is the single source of truth for the computation shared by {@code OwnerMapper} (the
24	 * {@code membershipPoints} and {@code membershipLevel} response fields) and the create audit line.
25	 */
26	public final class MembershipLevel {
27	
28	    /** The highest level this rule awards. */
29	    public static final int MAX = 4;
30	
31	    /** Points added when the owner has an email. */
32	    public static final int POINTS_EMAIL = 2;
33	
34	    /** Points added when the owner's name was unique on create ({@code namesakeCount} is 0). */
35	    public static final int POINTS_UNIQUE_NAME = 1;
36	
37	    /** Points added for a household of {@link #HOUSEHOLD_SIZE_FOR_POINTS} or more members. */
38	    public static final int POINTS_HOUSEHOLD = 2;
39	
40	    /** Points added when the owner's tenure exceeds {@link #TENURE_DAYS_FOR_POINTS} days. */
41	    public static final int POINTS_TENURE = 3;
42	
43	    /** A household needs at least this many members to earn {@link #POINTS_HOUSEHOLD}. */
44	    public static final int HOUSEHOLD_SIZE_FOR_POINTS = 3;
45	
46	    /** An owner must have been registered for more than this many days to earn {@link #POINTS_TENURE}. */
47	    public static final long TENURE_DAYS_FOR_POINTS = 365;
48	
49	    private MembershipLevel() {
50	    }
51	
52	    /**
53	     * Compute the membership points for an owner.
54	     *
55	     * @param owner the owner; its {@code email}, {@code namesakeCount}, {@code householdMemberCount}
56	     *              and tenure drive the result
57	     * @return the points total, 0 or greater
58	     */
59	    public static int points(Owner owner) {
60	        int points = 0;
61	        if (owner.hasEmail()) {
62	            points += POINTS_EMAIL;
63	        }
64	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
65	            points += POINTS_UNIQUE_NAME;
66	        }
67	        if (owner.getHouseholdMemberCount() != null
68	                && owner.getHouseholdMemberCount() >= HOUSEHOLD_SIZE_FOR_POINTS) {
69	            points += POINTS_HOUSEHOLD;
70	        }
71	        if (tenureDays(owner) > TENURE_DAYS_FOR_POINTS) {
72	            points += POINTS_TENURE;
73	        }
74	        return points;
75	    }
76	
77	    /**
78	     * Compute the membership level for an owner by mapping its {@link #points(Owner) points}.
79	     *
80	     * @param owner the owner
81	     * @return the level, between 1 and {@link #MAX} inclusive
82	     */
83	    public static int of(Owner owner) {
84	        return levelForPoints(points(owner));
85	    }
86	
87	    /**
88	     * Map a points total to a membership level: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, 4 for 6 or
89	     * more.
90	     *
91	     * @param points the points total
92	     * @return the level, between 1 and {@link #MAX} inclusive
93	     */
94	    public static int levelForPoints(int points) {
95	        if (points >= 6) {
96	            return 4;
97	        }
98	        if (points >= 4) {
99	            return 3;
100	        }
101	        if (points >= 2) {
102	            return 2;
103	        }
104	        return 1;
105	    }
106	
107	    /**
108	     * Days elapsed since the owner's registration date, or 0 when it is unknown (e.g. a brand-new
109	     * owner being created). Never negative for a future registration date.
110	     */
111	    private static long tenureDays(Owner owner) {
112	        LocalDate registrationDate = owner.getRegistrationDate();
113	        if (registrationDate == null) {
114	            return 0;
115	        }
116	        long days = ChronoUnit.DAYS.between(registrationDate, LocalDate.now());
117	        return Math.max(days, 0);
118	    }
119	}
120

